// HelpAnimalModal.js
import React, { Component } from "react";
import ChatComponent from "./ChatComponent";
import "./HelpAnimalModal.css";

class HelpAnimalModal extends Component {
  constructor(props) {
    super(props);
    this.state = {
      showModal: false,
    };
  }

  openModal = () => {
    this.setState({ showModal: true });
  };

  closeModal = () => {
    this.setState({ showModal: false });
  };

  render() {
    return (
      <div className="help-animal-modal">
        <button onClick={this.openModal}>Open Chat</button>
        {this.state.showModal && (
          <div className="modal">
            <div className="modal-content">
              <span className="close" onClick={this.closeModal}>&times;</span>
              <ChatComponent onEndChat={this.closeModal} />
            </div>
          </div>
        )}
      </div>
    );
  }
}

export default HelpAnimalModal;
